.command-overlay {
  position: fixed;
  inset: 0;
  z-index: var(--z-modal);
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding-block-start: 12vh;
  background: var(--overlay);
}
.command {
  inline-size: min(36rem, calc(100vw - var(--space-8)));
  background: var(--popover);

  color: var(--popover-foreground);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
}
.command-search {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-4);
  border-block-end: 1px solid var(--border);
}
.command-search-icon { color: var(--muted-foreground); }
.command-input {
  flex: 1;
  border: none;
  background: transparent;
  color: var(--foreground);
  font-family: inherit;
  font-size: var(--font-md);
}
.command-input:focus { outline: none; }
.command-list {
  margin: 0;
  padding: var(--space-2);
  list-style: none;
  max-block-size: 22rem;
  overflow-y: auto;
}
.command-item {
  min-height: var(--control-height);
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding-inline: var(--space-3);
  border-radius: var(--radius-md);
  font-size: var(--font-base);
  cursor: pointer;
}
.command-item-icon { color: var(--muted-foreground); }
.command-item-label { flex: 1; }
.command-item-hint {
  font-size: var(--font-xs);
  color: var(--muted-foreground);
  font-variant-numeric: tabular-nums;
}
.command-empty { padding: var(--space-4); text-align: center; font-size: var(--font-sm); color: var(--muted-foreground); }

/* WHERE ENTER WILL LAND — said by the row itself, not by a bar beside it.
 *
 * It was a 2px accent bar down the leading edge, argued from a contrast figure:
 * the fill alone measures 1.15:1 against this surface and a focus indicator is
 * asked for 3:1. The owner removed it twice (2026-08-24) and is right on both
 * counts — the row here is not DOM focus (focus stays in the input; the row is
 * named by aria-activedescendant), and the system already has one answer for
 * "this is the current row": the fill the sidebar uses for the current section.
 * So the active row takes --accent, a full step past the hover tint rather than
 * the half-step it was, and the mark is the row rather than an ornament on it.
 */
.command-item[data-active] { background: var(--accent); color: var(--accent-foreground); }
.command-item[data-active] .command-item-icon { color: var(--accent-foreground); }

import './CommandPalette.css'
import { useEffect, useId, useMemo, useRef, useState, type KeyboardEvent } from 'react'
import { createPortal } from 'react-dom'
import { cn } from '../lib/cn'
import { Icon, type IconName } from '../Icon'

export type Command = {
  id: string
  label: string
  icon?: IconName
  /** Extra searchable text (aliases, a section) not shown as the label. */
  keywords?: string
  /** Right-aligned hint, e.g. a shortcut. */
  hint?: string
  onRun: () => void
}

type Props = {
  open: boolean
  onClose: () => void
  commands: Command[]
  placeholder?: string
  emptyLabel?: string
  className?: string
}

/* The Cmd+K command palette: a centered search over an action list. Type to
 * filter, Arrow keys to move, Enter to run, Escape to close. The consumer owns
 * `open` (wire it to a global key handler) and what each command does. Portaled,
 * focus goes to the input on open. 
   *
   * Copy: the placeholder names the verbs this palette knows — "Search or jump
   * to…". Command names start with the verb, so a list of them reads as a
   * list of things you can do.
   */
export function CommandPalette({ open, onClose, commands, placeholder = 'Type a command or search…', emptyLabel = 'No results', className }: Props) {
  const [query, setQuery] = useState('')
  const [active, setActive] = useState(0)
  const inputRef = useRef<HTMLInputElement>(null)
  const listId = useId()

  const results = useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return commands
    return commands.filter((c) => (c.label + ' ' + (c.keywords ?? '')).toLowerCase().includes(q))
  }, [commands, query])

  useEffect(() => {
    if (open) {
      setQuery('')
      setActive(0)
      inputRef.current?.focus()
    }
  }, [open])

  useEffect(() => { setActive(0) }, [query])

  if (!open) return null

  const run = (cmd: Command) => { cmd.onRun(); onClose() }

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'ArrowDown') { e.preventDefault(); setActive((i) => Math.min(i + 1, results.length - 1)) }
    else if (e.key === 'ArrowUp') { e.preventDefault(); setActive((i) => Math.max(i - 1, 0)) }
    else if (e.key === 'Enter') { if (results[active]) { e.preventDefault(); run(results[active]) } }
    else if (e.key === 'Escape') { e.preventDefault(); onClose() }
  }

  return createPortal(
    // eslint-disable-next-line jsx-a11y/no-static-element-interactions -- backdrop click-to-dismiss; the dialog owns the role
    <div className="command-overlay" onMouseDown={(e) => { if (e.target === e.currentTarget) onClose() }}>
      <div className={cn('command', className)} data-raised="popover" role="dialog" aria-modal="true" aria-label="Command palette" onKeyDown={onKeyDown}>
        <div className="command-search">
          <Icon name="search" className="command-search-icon" />
          <input
            ref={inputRef}
            className="command-input"
            role="combobox"
            aria-expanded="true"
            aria-controls={listId}
            aria-autocomplete="list"
            aria-label="Search commands"
            placeholder={placeholder}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
        </div>
        <ul className="command-list" id={listId} role="listbox" aria-label="Commands">
          {results.length === 0 && <li className="command-empty" role="presentation">{emptyLabel}</li>}
          {results.map((cmd, i) => (
            <li
              key={cmd.id}
              role="option"
              aria-selected={i === active}
              className="command-item"
              data-active={i === active || undefined}
              onMouseDown={(e) => { e.preventDefault(); run(cmd) }}
              onMouseEnter={() => setActive(i)}
            >
              {cmd.icon && <Icon name={cmd.icon} size="sm" className="command-item-icon" />}
              <span className="command-item-label">{cmd.label}</span>
              {cmd.hint && <span className="command-item-hint">{cmd.hint}</span>}
            </li>
          ))}
        </ul>
      </div>
    </div>,
    document.body,
  )
}
